pragma solidity 0.8.30;
import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
contract RHStakingVault is IERC721Receiver, ReentrancyGuard {
    using SafeERC20 for IERC20;
    uint64 public constant EPOCH = 7 days;
    uint8 public constant MAX_TIER = 10;
    uint8 public constant PENDING = 11;
    uint16 public constant BASE_BPS = 10_000;
    uint16 public constant BPS_PER_TIER = 1_000;
    uint16 public constant MAX_MULT_BPS = 20_000;
    uint256 public constant MAX_REWARD_TOKENS = 8;
    uint32 public currentEpoch;
    uint64 public epochStartedAt;
    mapping(address account => uint32 startEpoch) public streakStartEpoch;
    mapping(address account => bool active) public hasStreak;
    uint32[12] private _countInTier;
    uint256 public totalWeight;
    struct RewardData {
        uint256 duration;
        uint256 periodFinish;
        uint256 rate;
        uint256 lastUpdate;
        uint256 rewardPerWeightStored;
        uint256 stranded;
    }
    address[] public rewardTokens;
    mapping(address token => RewardData) public rewardData;
    mapping(address token => mapping(uint32 epoch => uint256 rpw)) public rpwAtEpoch;
    event StreakEpochAdvanced(uint32 indexed epoch, uint64 ts, uint256 totalWeight);
    error EpochTooEarly();
    function multBps(uint8 tier) public pure returns (uint16) {
        uint16 m = BASE_BPS + BPS_PER_TIER * uint16(tier);
        return m > MAX_MULT_BPS ? MAX_MULT_BPS : m;
    }
    function tierAt(address account, uint32 epoch) public view returns (uint8) {
        if (!hasStreak[account]) return 0;
        uint32 s = streakStartEpoch[account];
        if (epoch <= s) return 0;
        uint32 t = epoch - s - 1;
        if (t > MAX_TIER) return MAX_TIER;
        return uint8(t);
    }
    function bucketsWeight() public view returns (uint256 w) {
        for (uint8 i = 0; i <= MAX_TIER; ++i) {
            w += uint256(_countInTier[i]) * multBps(i);
        }
        w += uint256(_countInTier[PENDING]) * BASE_BPS;
    }
    function bucketsCount() public view returns (uint256 c) {
        for (uint8 i = 0; i < 12; ++i) {
            c += _countInTier[i];
        }
    }
    function _bucketOf(address account) internal view returns (uint8) {
        if (!hasStreak[account]) return PENDING;
        uint32 s = streakStartEpoch[account];
        if (s >= currentEpoch) return PENDING;
        uint32 t = currentEpoch - s - 1;
        if (t > MAX_TIER) return MAX_TIER;
        return uint8(t);
    }
    function _recomputeTotalWeight() internal {
        totalWeight = bucketsWeight();
    }
    function _shiftTierBuckets() internal {
        _countInTier[MAX_TIER] += _countInTier[MAX_TIER - 1];
        for (uint8 i = MAX_TIER - 1; i > 0; --i) {
            _countInTier[i] = _countInTier[i - 1];
        }
        _countInTier[0] = _countInTier[PENDING];
        _countInTier[PENDING] = 0;
    }
    function advanceStreakEpoch() external {
        if (block.timestamp < epochStartedAt + EPOCH) revert EpochTooEarly();
        _updateGlobal(); // settle the accumulator at the OLD totalWeight
        uint32 next = currentEpoch + 1;
        uint256 len = rewardTokens.length;
        for (uint256 i; i < len; ++i) {
            address token = rewardTokens[i];
            rpwAtEpoch[token][next] = rewardData[token].rewardPerWeightStored;
        }
        _shiftTierBuckets();
        currentEpoch = next;
        epochStartedAt = uint64(block.timestamp);
        _recomputeTotalWeight();
        emit StreakEpochAdvanced(next, uint64(block.timestamp), totalWeight);
    }
}

