pragma solidity ^0.8.20;
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
interface IERC6551Registry {
    function account(address implementation, uint256 chainId, address tokenContract, uint256 tokenId, uint256 salt) external view returns (address);
    function createAccount(address implementation, uint256 chainId, address tokenContract, uint256 tokenId, uint256 salt, bytes calldata initData) external returns (address);
}
contract VestingController is Ownable {
    IERC20 public immutable POWERUSERS_TOKEN;
    IERC6551Registry public constant REGISTRY = IERC6551Registry(0x000000006551c194871ba62f43e49ca71Dce592c);
    uint256 public constant CLIFF = 90 days;
    uint256 public constant DURATION = 90 days;
    mapping(uint256 => uint256) public totalAllocations;
    mapping(uint256 => uint256) public claimed;
    uint256 public startTime;
    constructor(address _token) Ownable(msg.sender) {
        POWERUSERS_TOKEN = IERC20(_token);
        startTime = block.timestamp;
    }
    function claim(uint256 tokenId, address implementation, address nftContract) external {
        address tba = REGISTRY.account(implementation, block.chainid, nftContract, tokenId, 0);
        if (tba.code.length == 0) {
            REGISTRY.createAccount(implementation, block.chainid, nftContract, tokenId, 0, "");
        }
        uint256 vested = _vestedAmount(tokenId);
        uint256 claimable = vested - claimed[tokenId];
        require(claimable > 0, "Nothing to claim");
        claimed[tokenId] += claimable;
        require(POWERUSERS_TOKEN.transfer(tba, claimable), "Transfer failed");
    }
    function _vestedAmount(uint256 tokenId) internal view returns (uint256) {
        if (block.timestamp < startTime + CLIFF) return 0;
        if (block.timestamp >= startTime + CLIFF + DURATION) return totalAllocations[tokenId];
        return (totalAllocations[tokenId] * (block.timestamp - (startTime + CLIFF))) / DURATION;
    }
}
